public enum Motion {
    /// Entrances and exits ease out; on-screen movement eases in-out; drawers, popovers and page swaps use the drawer curve. No ease-in.
    public static let easeOut = TimingCurve(x1: 0.23, y1: 1, x2: 0.32, y2: 1)
    public static let easeInOut = TimingCurve(x1: 0.77, y1: 0, x2: 0.175, y2: 1)
    public static let easeDrawer = TimingCurve(x1: 0.32, y1: 0.72, x2: 0, y2: 1)
    /// A small mark arriving beside what it belongs to (the compaction divider's chevron): it leaves at once and takes most of its time settling, so a 160ms entrance reads as motion where ease-out reads as a swap.
    public static let easeArrive = TimingCurve(x1: 0.2, y1: 0, x2: 0, y2: 1)
    /// A glide's first stretch: speed rising evenly from rest (its position the square of its time), into the steady pace a tree's line, its room and the rows under it travel at.
    public static let easeGlideIn = TimingCurve(x1: 0.3333, y1: 0, x2: 0.6667, y2: 0.3333)
    /// A glide's last stretch: from the steady pace, speed falling evenly to rest.
    public static let easeGlideOut = TimingCurve(x1: 0.3333, y1: 0.6667, x2: 0.6667, y2: 1)
    /// Between one row of an opening tree and the next: its line reaches each in turn at a steady pace, one row's room per stagger.
    /// In seconds.
    public static let durStagger: TimeInterval = 0.06
    /// The most an opening tree's line takes to reach its last row: a longer tree's rows come closer together.
    /// In seconds.
    public static let durCascade: TimeInterval = 0.48
    /// The hover ghost following the pointer from row to row.
    /// In seconds.
    public static let durGhost: TimeInterval = 0.08
    /// In seconds.
    public static let durControl: TimeInterval = 0.12
    /// In seconds.
    public static let durMenu: TimeInterval = 0.14
    /// A switch's knob and a checkbox's tick.
    /// In seconds.
    public static let durToggle: TimeInterval = 0.16
    /// In seconds.
    public static let durExit: TimeInterval = 0.16
    /// A button's width following its label while it works.
    /// In seconds.
    public static let durMorph: TimeInterval = 0.18
    /// A transcript row's place opening, its rail drawing down with it.
    /// In seconds.
    public static let durRail: TimeInterval = 0.18
    /// Fades that carry a state change in place.
    /// In seconds.
    public static let durFade: TimeInterval = 0.2
    /// How long a wait runs before its loading state (Caw at loading or reconnecting) appears; a shorter wait shows its plain surface. NN/g, Response Times: no special feedback is needed for delays under 1.0 second.
    /// In seconds.
    public static let durWaitGrace: TimeInterval = 1
    /// In seconds.
    public static let durPop: TimeInterval = 0.26
    /// In seconds.
    public static let durPanel: TimeInterval = 0.28
